import{z as o,x as n,o as e,c as d,q as i,j as s,D as a,d as A,s as t,S as l,b as B}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"物化视图","description":"","frontmatter":{"title":"物化视图","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/qo-materialized-views.md","filePath":"cs/qo-materialized-views.md","lastUpdated":1791063341000}'),C={name:"cs/qo-materialized-views.md"};function p(F,E,h,D,c,m){const r=n("Mermaid");return e(),d("div",null,[E[2]||(E[2]=i('<h1 id="物化视图" tabindex="-1">物化视图 <a class="header-anchor" href="#物化视图" aria-label="Permalink to &quot;物化视图&quot;">​</a></h1><div class="epigraph"><p>物化视图是优化器的一次外置：把「这条查询会反复出现」的预测固化成存储。之后的每次命中都在为当初的预测收息，每次刷新都在付息。</p><footer>—— 据 Gupta and Mumick；Zaharioudakis et al., 2000；Agrawal, Chaudhuri and Narasayya, 2000 整理</footer></div><p><a href="/cs/qo-vectorized-deep">上一课</a>把执行摊到批上，让同一个计划跑得更快；物化视图换一条路——让计划根本不用跑。主干 <a href="/cs/mv-refresh">物化视图刷新</a> 钉了维护合同，<a href="/cs/star-schema">星型模式</a> 与 <a href="/cs/olap-cube">OLAP cube</a> 给了典型聚合形状。本课补齐另两半：查询怎么被改写成用视图（匹配与补偿），以及该物化哪些视图（工作负载驱动的选择）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>匹配的难点是查询与视图不逐字相同：查询比视图多一个过滤条件、列换了别名、外面又包了一层聚合。逐字匹配器只对上糖层，命中率低到没有工程价值。放行条件太松又危险：补偿谓词推导不完备，改写出的结果就是错的——错误的快比慢更贵。选择的难点是候选无限：每个分组维度组合、每种谓词组合都能成视图，而存储与刷新预算有限。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>匹配按强度分档。语法档：归一化后逐字对照，只能救缓存命中式的重复查询。语义档：把查询的选择—投影—连接结构映射进视图定义，证明视图包含查询所需元组集，把差出的谓词作为补偿条件叠在视图扫描上——例如视图没有地区过滤而查询有，就在视图上补一个 \\(\\sigma_\\mathrm{region}\\)。代价档：匹配成功不等于该用，「扫视图」与「扫基表」要放进同一个代价模型比较——第一课的接口在此再次出场。选择是离线任务：输入是带频率的工作负载与基表更新率；从负载里挖候选（常用的分组列子集、连接子集）；收益是节省代价乘频率、减去维护代价；预算约束下的选集是 NP-hard（与集合覆盖同族），工程用贪心：每轮加入边际收益最大的候选，数据库自带的自动顾问就是把这套跑成定期任务。</p>',7)),(e(),s(l,null,{default:a(()=>[t(r,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20LOAD%5B%22%E5%B7%A5%E4%BD%9C%E8%B4%9F%E8%BD%BD%20%2B%20%E6%9B%B4%E6%96%B0%E7%8E%87%22%5D%20--%3E%20MINE%5B%22%E6%8C%96%E5%80%99%E9%80%89%EF%BC%9A%E5%88%86%E7%BB%84%20%2F%20%E8%BF%9E%E6%8E%A5%E5%AD%90%E9%9B%86%22%5D%0A%20%20MINE%20--%3E%20GREED%5B%22%E9%A2%84%E7%AE%97%E5%86%85%E8%B4%AA%E5%BF%83%E9%80%89%E9%9B%86%22%5D%0A%20%20GREED%20--%3E%20CAT%5B%22%E7%99%BB%E8%AE%B0%E8%A7%86%E5%9B%BE%E5%B9%B6%E6%94%B6%E9%9B%86%E7%BB%9F%E8%AE%A1%22%5D%0A%20%20Q%5B%22%E7%94%A8%E6%88%B7%E6%9F%A5%E8%AF%A2%22%5D%20--%3E%20MATCH%5B%22%E5%BD%92%E4%B8%80%E5%8C%96%E4%B8%8E%E8%AF%AD%E4%B9%89%E5%8C%B9%E9%85%8D%22%5D%0A%20%20CAT%20--%3E%20MATCH%0A%20%20MATCH%20--%3E%20COMP%5B%22%E8%A1%A5%E5%81%BF%E8%B0%93%E8%AF%8D%E6%8E%A8%E5%AF%BC%22%5D%0A%20%20COMP%20--%3E%20EST%5B%22%E4%BB%A3%E4%BB%B7%E6%AF%94%E8%BE%83%EF%BC%9A%E8%A7%86%E5%9B%BE%20vs%20%E5%9F%BA%E8%A1%A8%22%5D%0A%20%20EST%20--%3E%20RW%5B%22%E6%94%B9%E5%86%99%E6%89%A7%E8%A1%8C%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B("h2",{id:"机制",tabindex:"-1"},[A("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=B("p",null,"匹配是改写不是提示（主干口径）：改写后的树仍走完整优化，因为视图可能比基表更歪或更陈旧。陈旧度要进匹配条件：延迟刷新的视图只服务接受陈旧的查询，可接受陈旧度是匹配器的输入——与刷新课的隔离语义绑死。视图自己也要收集统计：没统计的视图即使匹配上了也不敢用，代价无从比较。刷新代价进收益模型：高频更新的基表上建重聚合视图，利息可能收不回本金——这是把代价模型从「选计划」推广到「选存储」：物化决策与计划决策共用同一把尺子。",-1)),(e(),s(l,null,{default:a(()=>[t(r,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E4%B8%80%E6%9D%A1%E6%9F%A5%E8%AF%A2%E8%BF%9B%E6%9D%A5%22%5D%20--%3E%20SYN%7B%22%E8%AF%AD%E6%B3%95%E6%A1%A3%EF%BC%9A%E5%BD%92%E4%B8%80%E5%8C%96%E5%90%8E%E9%80%90%E5%AD%97%E7%9B%B8%E5%90%8C%EF%BC%9F%22%7D%0A%20%20SYN%20--%3E%7C%22%E6%98%AF%22%7C%20USE%5B%22%E7%9B%B4%E6%8E%A5%E7%94%A8%E8%A7%86%E5%9B%BE%22%5D%0A%20%20SYN%20--%3E%7C%22%E5%90%A6%22%7C%20SEM%7B%22%E8%AF%AD%E4%B9%89%E6%A1%A3%EF%BC%9A%E9%80%89%E6%8B%A9-%E6%8A%95%E5%BD%B1-%E8%BF%9E%E6%8E%A5%E7%BB%93%E6%9E%84%E5%8F%AF%E6%98%A0%E5%B0%84%E8%BF%9B%E8%A7%86%E5%9B%BE%E5%AE%9A%E4%B9%89%EF%BC%9F%22%7D%0A%20%20SEM%20--%3E%7C%22%E5%90%A6%22%7C%20BASE%5B%22%E6%89%AB%E5%9F%BA%E8%A1%A8%22%5D%0A%20%20SEM%20--%3E%7C%22%E6%98%AF%22%7C%20COMP%5B%22%E6%8E%A8%E5%AF%BC%E8%A1%A5%E5%81%BF%E8%B0%93%E8%AF%8D%E5%8F%A0%E5%9C%A8%E8%A7%86%E5%9B%BE%E6%89%AB%E6%8F%8F%E4%B8%8A%22%5D%0A%20%20COMP%20--%3E%20COST%7B%22%E4%BB%A3%E4%BB%B7%E6%A1%A3%EF%BC%9A%E6%89%AB%E8%A7%86%E5%9B%BE%E7%9C%9F%E7%9A%84%E6%9B%B4%E4%BE%BF%E5%AE%9C%EF%BC%9F%22%7D%0A%20%20COST%20--%3E%7C%22%E6%98%AF%22%7C%20USE%0A%20%20COST%20--%3E%7C%22%E5%90%A6%22%7C%20BASE%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=i('<p><span class="marginnote">Oracle 的查询改写强度分档：ENFORCED 只信已验证的约束，TRUSTED 允许信任未验证的声明，STALE_TOLERATED 接受过期视图。分档的本质是用多少正确性证据换匹配率——它是运维旋钮，不是默认值。</span></p><p><span class="marginnote">直觉类比：物化视图像后厨预先备好的半成品——客人点「红烧肉盖饭」时不用从杀猪开始，热一下就行（命中收息）；但每批猪肉进货后都得把半成品的账补上（刷新付息）。备哪些半成品，就看菜单上哪些菜点得多。</span></p><p><span class="marginnote">数字实例：收益公式的代账方式——某视图让一条查询从 3 秒降到 1 秒，省 2 秒，负载里它每天出现 1000 次，日收益 2000 秒；基表每小时更新、每次刷新花 10 秒，日维护 240 秒；净值大幅为正，值得物化。反过来查询一天只跑 10 次而基表高频更新，账就是亏的。</span></p><p><span class="marginnote">常见误区：初学者容易以为「匹配上了就该用视图」。实际上匹配成功只是门票：视图可能没有统计（代价无从比较）、可能太陈旧、可能比扫基表还贵；更有甚者，补偿谓词推导不完备时改写会产出错误结果——错误的快比慢更贵。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>立即刷新的一致性代价与锁开销是事务接口，本课不展开；流式与连续物化归分析与流单元。手写汇总表没有定义，就没有匹配、没有维护合同——<a href="/cs/5nf-denormalization">反规范化</a>课的警告在此重申。匹配器依赖声明而非猜测：UNIQUE、外键、函数依赖这些约束越全，可证明的包含关系越多——<a href="/cs/index-selection">索引选择</a>课的「物理设计服务改写」在这里再延伸一层。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>匹配分语法、语义、代价三档；补偿谓词推导不完备就是错误结果。</li><li>选择是预算下的 NP-hard 选集；负载驱动加贪心是工程默认。</li><li>视图要统计、要陈旧预算；匹配成功后仍走完整优化。</li><li>收益减维护：物化是把代价模型推广到存储决策。</li><li>出处：Gupta and Mumick；Zaharioudakis et al., 2000；Agrawal, Chaudhuri and Narasayya, 2000。</li></ul>',8))])}const f=o(C,[["render",p]]);export{T as __pageData,f as default};
